// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 count) public {
        vm.assume(count > 0 && count <= 1000);
        address me = address(0x1234);
        vm.deal(me, count * 1 ether);
        vm.startPrank(me);
        for (uint i = 0; i < count; i++) {
            (bool ok,) = address(c).call{value: 1 ether}("");
            require(ok, "receive failed");
        }
        vm.stopPrank();
        assertTrue(c.depositsCount() == count);
    }
}
